-- database/migrations/001_add_shared_trips.sql
--
-- Adds the shared_trips table to support Trip Sharing (Activity 5.2).
-- Run this in the Supabase SQL Editor (or any PostgreSQL client connected
-- to the project database).  It is safe to run multiple times thanks to
-- the IF NOT EXISTS guards.
--
-- SECURITY NOTES:
--   • share_token is generated by the backend using secrets.token_urlsafe(32).
--   • No user PII is stored in this table.
--   • The CASCADE on trip_id means shared tokens are automatically
--     removed when a trip is deleted.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Create the shared_trips table
CREATE TABLE IF NOT EXISTS shared_trips (
    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id     UUID        NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    share_token VARCHAR(64) UNIQUE NOT NULL,
    is_active   BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 2. Fast look-up by token (public share page)
CREATE INDEX IF NOT EXISTS idx_shared_trips_token
    ON shared_trips(share_token);

-- 3. Fast look-up by trip_id (owner management)
CREATE INDEX IF NOT EXISTS idx_shared_trips_trip_id
    ON shared_trips(trip_id);

-- 4. Only one active share per trip (optional uniqueness constraint)
--    If you want to allow multiple tokens per trip, comment this out.
CREATE UNIQUE INDEX IF NOT EXISTS uq_shared_trips_active_trip
    ON shared_trips(trip_id)
    WHERE is_active = TRUE;

